handlers.scope.fnSetServerFileUpDownSqno:
async function(nowIndex, sumSq) {
    if(nowIndex == 0 && sumSq < 0) return;
    if(nowIndex == dlUntyAtchFileL.getTotalRow()-1 && sumSq > 0) return;
    let ableFileSize = dlUntyAtchFileL.getAllJSON().filter(row => (row.rowStatus !== "E" && row.rowStatus !== "D")).length;
    let targetIndex = nowIndex + sumSq;
    /*
    if(targetIndex + 1 > ableFileSize) {
        targetIndex = ableFileSize - 1;
    }
    */
    console.log("index Change >> ", nowIndex, targetIndex);
    for(let idx=0; idx<dlUntyAtchFileL.getTotalRow(); idx++) {
        let orgStatus = dlUntyAtchFileL.getRowStatus(idx);
        let scrnIndtOdr;
        if(idx != targetIndex
        && idx != nowIndex) {
            scrnIndtOdr = idx;
        }else {
            if(idx == targetIndex) {
                scrnIndtOdr = nowIndex;
            }else {
                scrnIndtOdr = targetIndex;
            }
        }
        dlUntyAtchFileL.setCellData(idx, "scrnIndtOdr", scrnIndtOdr + 1);
        if(orgStatus === "C" || orgStatus === "E" || orgStatus === "D") {
            dlUntyAtchFileL.modifyRowStatus(idx, orgStatus);
        }
    }
}

handlers.scope.btnRowDown_onclick:
async function (e) {
    let rowPosition = dlUntyAtchFileL.getRowPosition();
    //전체선택 null 처리
    if(rowPosition === null) return;

    // 부모가 지정한 함수 동기처리
    if(typeof scwin.options.evPreBtnRowDown === "function") {
        let isContinue = await scwin.options.evPreBtnRowDown(scwin.fileScope);
        if(isContinue === false) {
            return;
        }
    }

    if(scwin.options.isServerRowMove) {
        RAONKUPLOAD.SetSelectFile(rowPosition, 0, scwin.kUploadId);
        RAONKUPLOAD.MoveBackwardFile(scwin.kUploadId);
        scwin.fnSetServerFileUpDownSqno(rowPosition, 1);
        scwin.fnDataListRowMove(dlUntyAtchFileL, rowPosition, 1);
        scwin.resetFileIndex();
    }else {
        if (comUtil.gfnIsNotEmpty(dlUntyAtchFileL.getCellData(rowPosition, "atchFileSqno"))) {
            com.gfnAlert(["msg.alert.notMoveAttachFile"]);
        }else {
            if (comUtil.gfnIsNotEmpty(dlUntyAtchFileL.getCellData(rowPosition + 1, "atchFileSqno"))) {
                com.gfnAlert(["msg.alert.notMoveAttachFileRow"]);
            }else {
                RAONKUPLOAD.SetSelectFile(rowPosition, 0, scwin.kUploadId);
                RAONKUPLOAD.MoveBackwardFile(scwin.kUploadId);
                scwin.fnSetServerFileUpDownSqno(rowPosition, 1);
                scwin.fnDataListRowMove(dlUntyAtchFileL, rowPosition, 1);
                scwin.resetFileIndex();
            }
        }
    }
}

