handlers.scopeVariable.fnSetServerFileUpDownSqno:
async function(nowIndex, sumSq) {
    if(nowIndex == 0 && sumSq < 0) return;
    if(nowIndex == dlUntyAtchFileL.getTotalRow()-1 && sumSq > 0) return;
    let ableFileSize = dlUntyAtchFileL.getAllJSON().filter(row => (row.rowStatus !== "E" && row.rowStatus !== "D")).length;
    let targetIndex = nowIndex + sumSq;
    /*
    if(targetIndex + 1 > ableFileSize) {
        targetIndex = ableFileSize - 1;
    }
    */
    console.log("index Change >> ", nowIndex, targetIndex);
    for(let idx=0; idx<dlUntyAtchFileL.getTotalRow(); idx++) {
        let orgStatus = dlUntyAtchFileL.getRowStatus(idx);
        let scrnIndtOdr;
        if(idx != targetIndex
        && idx != nowIndex) {
            scrnIndtOdr = idx;
        }else {
            if(idx == targetIndex) {
                scrnIndtOdr = nowIndex;
            }else {
                scrnIndtOdr = targetIndex;
            }
        }
        dlUntyAtchFileL.setCellData(idx, "scrnIndtOdr", scrnIndtOdr + 1);
        if(orgStatus === "C" || orgStatus === "E" || orgStatus === "D") {
            dlUntyAtchFileL.modifyRowStatus(idx, orgStatus);
        }
    }
}

