handlers.scopeVariable.dlUntyAtchFileL_oncelldata:
async function(info) {
    // 부모가 지정한 함수 동기처리
    if(typeof scwin.options.evCellDataChange === "function") {
        let colID    = info.colID;
        let rowIndex = info.rowIndex;
        let newValue = info.newValue;
        let oldValue = info.oldValue;
        //그리드에 매핑되어 있는 컬럼인지 검증
        if(grdFile.getColumnIndex(colID) < 0) return;
        //그리드에 해당 컬럼이 표출되고 있는지 검증
        if(grdFile.getColumnVisible(colID) === false) return;
        //그리드에 사용자가 변경 가능한 셀인지 검증
        if(grdFile.getCellReadOnly(rowIndex, colID) === true) return;

        let isContinue = await scwin.options.evCellDataChange(scwin.fileScope, info);
        if(isContinue === false) {
            // 리턴값이 false인경우 이전값으로 재설정 (이벤트 pause)
            dlUntyAtchFileL.unbind('oncelldatachange');
            dlUntyAtchFileL.setCellData(rowIndex, colID, oldValue);
            dlUntyAtchFileL.bind('oncelldatachange', scwin.dlUntyAtchFileL_oncelldatachange)
        }
    }
}

handlers.scopeVariable.previewAtchFile:
async function(untyAtchFileNo, atchFileSqno, option) {
    dlDownAtflGrpDetlM.set("untyAtchFileNo", untyAtchFileNo);
    dlDownAtflGrpDetlM.set("atchFileSqno", atchFileSqno);

    // 미리보기를 위한 서브미션
    const sbmOption = {
        id: "smbDownAtflGrpDetlM",
        action: "/fs/fsc/fsca/atchFileDocViewer.do",
        inData: "dlDownAtflGrpDetlM",
        outData: "dlDownAtflGrpDetlResultM=result",
        msgYn: { succ: false, err: true },
    };

    const result = await com.gfnExecute(sbmOption);
    if (result.responseStatusCode === 200) {
        let previewWindow;
        if(comUtil.gfnIsEmpty(option)) {
            previewWindow = window.open("about:blank");
        }else {
            let sOption = "";
            Object.keys(option).forEach((key, idx) => {
                sOption += key + "=" + option[key] + ((idx !== Object.keys(option).length -1) ? "," : "");
            })
            previewWindow = window.open("about:blank", "previewPopup", sOption);
        }
        previewWindow.location.href = dlDownAtflGrpDetlResultM.get("viewUrlPath");
    }
}
